<template>
  <view class="pilot">
    <view class="top"><view class="brand"><view class="brand-icon"><text></text><text></text></view><view><view class="brand-name">在线组队</view><view class="brand-caption">PLAYER MATCH</view></view></view><text class="badge"><text class="live-indicator">●</text> 烽火地带 · 两人组队</text></view>
    <view class="page-heading"><view><view class="headline">{{tab==='我的组局'?'我的组队':'寻找在线合拍玩家'}}</view><view class="intro">{{tab==='本局条件'?'设置合作目的、装备配置与队友要求':tab==='招募大厅'?'浏览玩家招募，选择符合预期的队友':'查看组队状态，与队友交换信息'}}</view></view><text class="heading-tag">DELTA FORCE · OPERATIONS</text></view>
    <view class="tabs"><button v-for="t in ['本局条件','招募大厅','我的组局']" :key="t" :class="{active:tab===t}" @click="switchTab(t)">{{t}}</button></view>
    <view v-if="error" class="error" role="alert">{{error}}</view><view v-if="state.notice" class="notice">{{state.notice.replace(/。$/,'')}}</view><view v-if="state.squad?.status==='proposed' && tab!=='我的组局'" class="warning">有待确认的队友，剩余 {{confirmRemaining}} 秒<button class="btn-secondary" @click="switchTab('我的组局')">查看本局约定</button></view>
    <view v-if="tab==='本局条件'" class="plan-layout">
      <view class="form-progress"><view><b>本局招募</b><text class="progress-copy"> {{filledCount}} / {{requiredKeys.length}} 项必填已完成</text></view><text class="draft-note">自动保存草稿</text><view class="progress-track"><view :style="{width:(filledCount/requiredKeys.length*100)+'%'}"/></view></view><view class="panel-pilot"><view class="section-num"><text class="section-index">01</text> 合作目的<text class="section-detail">这局要做什么</text></view><view class="choices"><button v-for="g in goals" :key="g" :class="{chosen:form.goal===g}" @click="form.goal=g">{{g}}</button></view><view class="small">{{goalNotes[form.goal]}}</view>
      <view v-if="form.goal==='33任务'" class="task-groups divider"><view class="subsection-title">33任务 · 选择具体任务</view><view v-for="group in taskGroups" :key="group.label" class="task-group"><text class="task-category">{{group.label}}</text><view class="choices task-options"><button v-for="task in group.values" :key="task" :class="{chosen:form.task===task}" @click="form.task=task">{{task}}</button></view></view></view>
      </view><view v-if="form.goal!=='跑刀'" class="panel-pilot"><view class="section-num"><text class="section-index">02</text> 装备配置<text class="section-detail">护甲与子弹等级</text></view>
      <view v-if="form.goal!=='跑刀'" class="form-grid"><view class="field-group" v-for="item in gearFields" :key="item.key">{{item.label}}<view class="level-options" role="group" :aria-label="item.label"><button v-for="level in 5" :key="level" class="level-option" :class="{selected:form[item.key]===level}" :aria-pressed="form[item.key]===level" @click="form[item.key]=level"><text>{{level}}</text><text class="level-unit">级</text></button></view></view></view>
      </view><view class="panel-pilot"><view class="section-num"><text class="section-index">{{form.goal==='跑刀'?'02':'03'}}</text> 自身配置与队友要求<text class="section-detail">打法与实力</text></view>      <view class="form-grid"><view class="field-group" v-for="item in styleFields" :key="item.key">{{item.label}}<view class="style-options" role="group" :aria-label="item.label"><button v-for="(style,index) in styleLabels" :key="style" class="style-option" :class="{selected:form[item.key]===index+1}" :aria-pressed="form[item.key]===index+1" @click="form[item.key]=index+1"><text class="style-number">{{index+1}}</text><text>{{style}}</text></button></view></view></view>
<view class="subsection-title divider">硬核实力</view><view class="small strength-guidance">请按真实数据填写，实力差距过大会影响双方体验</view>
      <view class="form-grid stats-grid"><label id="field-confidential_kd" class="required-field" :class="{invalid:fieldError('confidential_kd')}"><view class="field-label">机密 KD<text class="required-star">*</text><text v-if="isEmpty(form.confidential_kd)" class="missing-tag">待填写</text></view><input v-model.number="form.confidential_kd" type="digit" placeholder="例如 1.5" placeholder-style="color:#718096" @blur="touched.confidential_kd=true"/><text v-if="fieldError('confidential_kd')" class="field-error">{{fieldError('confidential_kd')}}</text></label><label id="field-top_secret_kd" class="required-field" :class="{invalid:fieldError('top_secret_kd')}"><view class="field-label">绝密 KD<text class="required-star">*</text><text v-if="isEmpty(form.top_secret_kd)" class="missing-tag">待填写</text></view><input v-model.number="form.top_secret_kd" type="digit" placeholder="例如 2.0" placeholder-style="color:#718096" @blur="touched.top_secret_kd=true"/><text v-if="fieldError('top_secret_kd')" class="field-error">{{fieldError('top_secret_kd')}}</text></label><label id="field-combat_score" class="required-field" :class="{invalid:fieldError('combat_score')}"><view class="field-label">战斗分<text class="required-star">*</text><text v-if="isEmpty(form.combat_score)" class="missing-tag">待填写</text></view><input v-model.number="form.combat_score" type="digit" placeholder="例如 50" placeholder-style="color:#718096" @blur="touched.combat_score=true"/><text v-if="fieldError('combat_score')" class="field-error">{{fieldError('combat_score')}}</text></label></view>
      <strength-score :value="strengthScore"/>
      <view class="form-grid divider"><label id="field-strength_min" class="required-field" :class="{invalid:fieldError('strength_min')}"><view class="field-label">队友最低实力分<text class="required-star">*</text><text v-if="isEmpty(form.strength_min)" class="missing-tag">待填写</text></view><input v-model.number="form.strength_min" type="digit" placeholder="例如 60" placeholder-style="color:#718096" @blur="touched.strength_min=true"/><text v-if="fieldError('strength_min')" class="field-error">{{fieldError('strength_min')}}</text></label><label id="field-strength_max" class="required-field" :class="{invalid:fieldError('strength_max')}"><view class="field-label">队友最高实力分<text class="required-star">*</text><text v-if="isEmpty(form.strength_max)" class="missing-tag">待填写</text></view><input v-model.number="form.strength_max" type="digit" placeholder="例如 150" placeholder-style="color:#718096" @blur="touched.strength_max=true"/><text v-if="fieldError('strength_max')" class="field-error">{{fieldError('strength_max')}}</text></label></view>
      </view><view class="panel-pilot"><view v-if="localSaveFailed" class="warning">浏览器暂时无法保存资料，你仍可继续使用，但刷新后可能需要重新填写</view><view class="section-num"><text class="section-index">{{form.goal==='跑刀'?'03':'04'}}</text> 基础信息<text class="section-detail">先确认能一起玩</text></view><view class="form-grid base-grid">
        <label id="field-nickname" class="required-field" :class="{invalid:fieldError('nickname')}"><view class="field-label">队内昵称<text class="required-star">*</text><text v-if="isEmpty(form.nickname)" class="missing-tag">待填写</text></view><input v-model="form.nickname" type="text" maxlength="24" placeholder="怎么称呼你" placeholder-style="color:#718096" @blur="touched.nickname=true"/><text v-if="fieldError('nickname')" class="field-error">{{fieldError('nickname')}}</text></label>

        <view class="field-group" v-for="field in fields" :key="field.key">{{field.label}}<dark-select v-model="form[field.key]" :options="field.values" :label="field.label" :option-labels="field.labels||{}"/></view>
      </view><view class="local-save-row"><button class="save-local" @click="saveLocalDraft">{{localSaved?'✓ 已保存到本地':'保存到本地'}}</button><text class="save-local-note" :class="{saved:localSaved}">{{localSaveFailed?'保存失败，请检查浏览器存储权限':'下次打开自动加载'}}</text></view>
      </view><view class="panel-pilot"><view class="section-num"><text class="section-index">{{form.goal==='跑刀'?'04':'05'}}</text> 发布招募<text class="section-detail">选择找队友的方式</text></view><view class="choices"><button :class="{chosen:form.discovery==='browse'}" @click="form.discovery='browse'">看推荐，自己挑</button><button :class="{chosen:form.discovery==='auto'}" @click="form.discovery='auto'">系统自动找</button></view><view class="small">自己挑选队友，或让系统帮你寻找</view><label class="public-choice">公开我的本局招募<switch :checked="form.public" @change="form.public=$event.detail.value" color="#286952"/></label><view class="small">让其他玩家在大厅看到你的组队需求，双方确认后即可聊天</view><view v-if="submitted && Object.keys(validationErrors).length" class="validation-summary" role="alert">还有 {{Object.keys(validationErrors).length}} 项需要检查，请完成标红的字段</view><button class="btn-primary submit" :disabled="busy || activeTicket" @click="join">{{activeTicket?'已有组局，可去大厅或「我的组局」':'提交条件，寻找一位队友'}}</button>
      </view>

    </view>
    <view v-if="tab==='招募大厅'">
      <view v-if="state.ticket && !activeTicket" class="notice">{{state.ticket.status==='expired'?'你的招募已过期，重新发布后即可申请组队':'你可以浏览招募，发布本局条件后再申请组队'}}<button class="btn-secondary" @click="tab='本局条件'">填写本局条件</button></view><view v-if="activeTicket" class="notice">{{state.ticket?.status==='matched'?'已有待确认队友，请前往「我的组局」处理':'招募中，你可以主动选择队友'}}</view>
      <pilot-candidates :items="candidates.items" :total="candidates.total" :page="candidatePage" :recommended="recommended" :can-recommend="candidates.can_recommend" :busy="busy" :waiting="state.ticket?.status==='waiting'" :my-status="candidates.my_status" @refresh="loadCandidates" @mode="setCandidateMode" @edit="tab='本局条件'" @invite="invite" @page="changePage" @skip="skipBatch"/>
    </view>
    <view v-if="tab==='我的组局'">
      <view v-if="!state.ticket" class="panel-pilot empty"><view class="aside-title">还没有本局计划</view><view class="muted">先告诉队友，你这次想怎么玩</view><button class="btn-primary submit" @click="tab='本局条件'">填写本局条件</button></view>
      <view v-else-if="!state.squad" class="panel-pilot empty"><view class="section-num">{{state.ticket.status==='waiting'?'正在寻找队友':'本次排队已结束'}}</view><view class="aside-title">{{state.ticket.status==='waiting'?'等待符合条件的真人玩家':'准备好，再出发'}}</view><view class="muted">可以到大厅主动找队友。招募有效期为 20 分钟，过期后可重新发布</view><view class="small">条件：{{state.ticket.profile.region}} · {{state.ticket.profile.map}} · {{profileSummary(state.ticket.profile)}}</view><button v-if="state.ticket.status==='waiting'" class="btn-primary submit" @click="switchTab('招募大厅')">查看推荐队友</button><button v-if="activeTicket" class="btn-secondary submit" :disabled="busy" @click="act('cancel')">取消本次排队</button><button v-else class="btn-primary submit" @click="tab='本局条件'">重新填写</button></view>
      <view v-else class="layout"><view><pilot-chat v-if="['ready','done'].includes(state.squad.status)" :key="state.squad.id" :squad-id="state.squad.id" :token="token"/><view class="panel-pilot"><view class="section-num">{{statusLabel}}</view><view class="aside-title">{{state.squad.status==='proposed'?'先确认约定，再进游戏':'队伍已就绪，聊聊再出发'}}</view><view v-if="state.squad.status==='proposed'" class="warning">剩余 {{confirmRemaining}} 秒，请双方确认。超时释放名额，保留排队进度</view><view class="members"><view v-for="m in state.squad.members" :key="m.id" class="member"><view class="avatar-pilot">{{m.profile.nickname.slice(0,1)}}</view><b>{{m.profile.nickname}}{{m.is_me?'（我）':''}}</b><view class="muted">{{m.profile.strength_score!==undefined?'实力分 '+m.profile.strength_score:ranks[m.profile.rank-1]}}</view><view class="small">{{profileSummary(m.profile)}}<br/>{{m.profile.voice}} · 玩家自报</view><view class="status-text">{{m.confirmed?'✓ 已确认':'等待确认'}}</view><view v-if="['ready','done'].includes(state.squad.status) && m.profile.game_id">游戏 ID：{{m.profile.game_id}}</view></view></view>

      <view class="agreement"><b>本局约定</b><view>目标：{{state.squad.agreement.goal}}</view><view v-if="state.squad.members[0].profile.strength_score!==undefined">{{profileSummary(state.squad.members[0].profile)}}</view><view v-else>共同预算：{{state.squad.agreement.budget_min}}–{{state.squad.agreement.budget_max}} 万 / 人</view><view>{{state.squad.members[0].profile.region}} · {{state.squad.members[0].profile.map}} · {{state.squad.members[0].profile.difficulty}} · {{state.squad.members[0].profile.slot}}</view></view><view class="small">{{state.squad.agreement.scope.replace(/。$/,'')}}</view>
      <button v-if="state.squad.status==='proposed'" class="btn-primary submit" :disabled="busy || myMember.confirmed" @click="act('confirm')">{{myMember.confirmed?'你已确认，等待队友':'我已看清条件并接受本局约定'}}</button><view v-if="state.squad.status==='proposed'" class="reject-box"><view class="field-group">不合适？请选择原因<dark-select :model-value="rejectReasons[rejectIndex].label" :options="rejectReasons.map(r=>r.label)" label="婉拒原因" @update:model-value="rejectIndex=rejectReasons.findIndex(r=>r.label===$event)"/></view><button class="btn-secondary submit" :disabled="busy" @click="rejectProposal">婉拒并继续找 · 原因不向队友公开</button></view><button v-if="['proposed','ready'].includes(state.squad.status) && !state.squad.feedback_submitted" class="btn-secondary submit" :disabled="busy" @click="cancelSquad">取消组局</button><button v-if="['done','cancelled'].includes(state.squad.status) || state.squad.feedback_submitted" class="btn-primary submit" @click="tab='本局条件'">发起下一局</button>
      </view></view>
      <view class="panel-pilot" v-if="['ready','done'].includes(state.squad.status)"><text class="eyebrow">局后独立反馈</text><view class="aside-title">下次还想一起玩吗？</view><view v-if="state.squad.feedback_submitted" class="notice">反馈已保存，谢谢你帮助我们改善匹配</view><view v-else><label>是否实际一起游玩？<view class="choices"><button :class="{chosen:review.played}" @click="review.played=true">已游玩</button><button :class="{chosen:!review.played}" @click="review.played=false">未游玩</button></view></label><view class="small" v-if="!review.played">告诉我们没能一起玩的原因，帮助下次找到更合适的队友</view><label v-for="item in reviewFields" :key="item.key">{{item.label}}<switch :checked="review[item.key]" @change="review[item.key]=$event.detail.value" color="#286952"/></label><label>愿意再次组队？<view class="choices"><button v-for="o in againOptions" :key="o.value" :class="{chosen:review.again===o.value}" @click="review.again=o.value">{{o.label}}</button></view></label><label>原因（可选）<textarea v-model="review.reason" maxlength="300" placeholder="区分水平差距、目标分歧与单纯输了比赛"/></label><button class="btn-primary submit" :disabled="busy || !review.again" @click="act('feedback',review)">提交本局反馈</button></view></view>
      </view>
    </view>
    <view class="footer">在线组队 · 烽火地带</view>
  </view>
</template>
<script setup>
import { ref, reactive, computed, watch } from 'vue'
import { onShow, onHide, onUnload } from '@dcloudio/uni-app'
import PilotCandidates from '../../components/pilot-candidates.vue'
import PilotChat from '../../components/pilot-chat.vue'
import DarkSelect from '../../components/dark-select.vue'
import StrengthScore from '../../components/strength-score.vue'
import { profileSummary, strengthBand, scoreOf } from '../../utils/recruitment.js'
import { API_BASE } from '../../config.js'
import { loadPreferences, savePreferences, pickPreferences } from '../../utils/pilot-preferences.js'
const tab=ref('本局条件'), busy=ref(false), error=ref(''), state=ref({}), config=ref({})
const candidates=ref({items:[],total:0,can_recommend:false}), recommended=ref(false), candidatePage=ref(0), rejectIndex=ref(0), clock=ref(Date.now())
const rejectReasons=[{value:'goal',label:'目标不同'},{value:'budget',label:'装备预算不合适'},{value:'skill',label:'实力预期不符'},{value:'communication',label:'沟通方式不合适'},{value:'time',label:'时间安排变化'},{value:'other',label:'其他原因'}]
let serverOffset=0, refreshing=false, tick=0, candidateLoadId=0
let timer=null, token=uni.getStorageSync('pilot-token')||''
const ranks=['青铜','白银','黄金','白金','钻石','黑鹰','巅峰'], skills=['1 · 初学','2 · 入门','3 · 熟练','4 · 进阶','5 · 高水平'], gaps=['仅同档','可相差 1 档','可相差 2 档','可相差 3 档','均可']
const skillNotes=['仍在学习地图与基础操作','能独立搜集，交战需要帮助','能报点、撤退与配合完成常规任务','能处理复杂交战并指挥协同','熟悉所选地图并能稳定处理高强度交战']
const goals=['33任务','跑刀','猛攻'], goalNotes={'33任务':'选择这局要完成的任务','跑刀':'轻装出发','猛攻':'以主动交战为主，先约定装备'}
const tasks=['调查','放置','带出撤离任务','击杀干员','击杀特殊兵种','普通局内任务','标杆任务','命运契约'], levels=['1 级','2 级','3 级','4 级','5 级'], styles=['1 · 很保守','2 · 偏保守','3 · 均衡','4 · 偏激进','5 · 很激进'], gearFields=[{key:'armor',label:'护甲'},{key:'ammo',label:'子弹'}], styleFields=[{key:'style',label:'我的打法风格'},{key:'partner_style',label:'队友的打法风格'}]
const styleLabels=['很保守','偏保守','均衡','偏激进','很激进']
const taskGroups=[{label:'跑图任务',values:['调查','放置','带出撤离任务']},{label:'击杀任务',values:['击杀干员','击杀特殊兵种']},{label:'局内行动',values:['普通局内任务','标杆任务']},{label:'命运契约',values:['命运契约']}]
const fields=[{key:'region',label:'区服',values:['NA','EU','SEA','OCE','ME']},{key:'platform',label:'游戏端',values:['PC','Console','Mobile'],labels:{PC:'电脑端',Console:'主机端',Mobile:'手机端'}},{key:'language',label:'沟通语言',values:['中文','English','日本語']},{key:'map',label:'地图',values:['零号大坝','长弓溪谷','巴克什']},{key:'difficulty',label:'难度',values:['简单','普通']},{key:'voice',label:'语音方式',values:['开麦','听指挥与标记']},{key:'slot',label:'开局时段',values:['现在起一小时','今天晚间']}]
const localPreferences=loadPreferences(uni)
let hasLocalDraft=localPreferences.found
const form=reactive(localPreferences.values)
const strengthScore=computed(()=>scoreOf(form))
const localSaveFailed=ref(false), localSaved=ref(false)
const submitted=ref(false), touched=reactive({})
const requiredKeys=['nickname','confidential_kd','top_secret_kd','combat_score','strength_min','strength_max']
const isEmpty=v=>v===''||v==null||(typeof v==='string'&&!v.trim())
const validationErrors=computed(()=>{
 const result={}
 const labels={nickname:'队内昵称',confidential_kd:'机密 KD',top_secret_kd:'绝密 KD',combat_score:'战斗分',strength_min:'队友最低实力分',strength_max:'队友最高实力分'}
 for(const key of requiredKeys){if(isEmpty(form[key]))result[key]='请填写'+labels[key];else if(key!=='nickname'&&(!Number.isFinite(Number(form[key]))||Number(form[key])<0))result[key]='请输入大于或等于 0 的有效数值'}
 for(const [key,max] of Object.entries({confidential_kd:1000,top_secret_kd:1000,combat_score:1000000,strength_min:1000000000,strength_max:1000000000})){if(!isEmpty(form[key])&&Number(form[key])>max)result[key]='数值不能超过 '+max}
 if(!isEmpty(form.strength_min)&&!isEmpty(form.strength_max)&&Number(form.strength_min)>Number(form.strength_max))result.strength_max='最高分不能低于最低分'
 return result
})
const filledCount=computed(()=>requiredKeys.filter(k=>!validationErrors.value[k]).length)
const fieldError=key=>(submitted.value||touched[key])?validationErrors.value[key]:''

function saveLocalDraft(){localSaveFailed.value=!savePreferences(uni,form);localSaved.value=!localSaveFailed.value;if(localSaved.value)hasLocalDraft=true}
watch(form,value=>{localSaved.value=false;hasLocalDraft=true;localSaveFailed.value=!savePreferences(uni,value)},{deep:true,flush:'sync'})
const review=reactive({played:true,again:'',goal_met:false,budget_met:false,skill_met:false,reason:''})
const reviewFields=[{key:'goal_met',label:'实际遵守了本局目标'},{key:'budget_met',label:'实际装备投入符合约定'},{key:'skill_met',label:'实际水平在可接受范围内'}], againOptions=[{value:'yes',label:'愿意'},{value:'unsure',label:'不确定'},{value:'no',label:'不愿意'}]
const activeTicket=computed(()=>['waiting','matched'].includes(state.value.ticket?.status))
const myMember=computed(()=>state.value.squad?.members.find(m=>m.is_me)||{})
const statusLabel=computed(()=>({proposed:'队友已找到 · 等待双方确认',ready:'双方已确认 · 在游戏内添加队友',done:'本次组局已完成',cancelled:'本次组局已取消'}[state.value.squad?.status]))
const confirmRemaining=computed(()=>Math.max(0,Math.ceil((Date.parse(state.value.squad?.deadline||'')-(clock.value+serverOffset))/1000))||0)
async function request(path,data){return new Promise((resolve,reject)=>uni.request({url:API_BASE+'/pilot/'+path,method:data===undefined?'GET':'POST',data,header:{Authorization:'Bearer '+token},success:r=>{if(r.statusCode>=400){let d=r.data.detail;reject(new Error(typeof d==='string'?d:'输入有误，请检查本局条件中的必填项'))}else resolve(r.data)},fail:()=>reject(new Error('连接暂时中断，请稍后重试'))}))}
function applyState(value){clock.value=Date.now();state.value=value;config.value=value.config;if(value.server_now)serverOffset=Date.parse(value.server_now)-Date.now()}
async function refresh(){if(refreshing)return;refreshing=true;try{applyState(await request('state'));error.value=''}catch(e){error.value=e.message}finally{refreshing=false}}
async function loadCandidates(){const id=++candidateLoadId;try{const value=await request('candidates?recommended='+recommended.value+'&page='+candidatePage.value);if(id===candidateLoadId)candidates.value=value}catch(e){if(id===candidateLoadId)error.value=e.message}}
function setCandidateMode(value){recommended.value=value;candidatePage.value=0;loadCandidates()}
function changePage(value){candidatePage.value=value;loadCandidates()}
async function invite(id){busy.value=true;error.value='';try{applyState(await request('invite',{candidate_id:id}));tab.value='我的组局'}catch(e){error.value=e.message;await loadCandidates()}finally{busy.value=false}}
async function skipBatch(){busy.value=true;error.value='';try{await request('skip',{candidate_ids:candidates.value.items.map(c=>c.id)});candidatePage.value=0;await loadCandidates()}catch(e){error.value=e.message}finally{busy.value=false}}
async function switchTab(t){tab.value=t;await refresh();if(t==='招募大厅')await loadCandidates()}
async function join(){submitted.value=true;if(Object.keys(validationErrors.value).length){const first=Object.keys(validationErrors.value)[0];uni.pageScrollTo({selector:'#field-'+first,duration:250});return}busy.value=true;error.value='';try{if(!form.nickname.trim())throw new Error('请填写昵称');if(strengthScore.value===null)throw new Error('请填写有效的机密 KD、绝密 KD 和战斗分');if(form.strength_min===''||form.strength_max===''||Number(form.strength_min)<0||Number(form.strength_max)<Number(form.strength_min))throw new Error('请填写有效的队友实力分范围');applyState(await request('join',{...form}));Object.assign(review,{played:true,again:'',goal_met:false,budget_met:false,skill_met:false,reason:''});tab.value=state.value.squad?'我的组局':form.discovery==='browse'?'招募大厅':'我的组局';if(tab.value==='招募大厅')await loadCandidates()}catch(e){error.value=e.message}finally{busy.value=false}}
async function act(action,data={}){busy.value=true;error.value='';try{applyState(await request(action,{...data,squad_id:state.value.squad?.id}));if(action==='reject'){tab.value='招募大厅';candidatePage.value=0;await loadCandidates()}}catch(e){error.value=e.message}finally{busy.value=false}}
function rejectProposal(){act('reject',{reason:rejectReasons[rejectIndex.value].value})}
function cancelSquad(){uni.showModal({title:'取消本次组局？',content:'你将退出本局，对方可以继续寻找队友',success:r=>{if(r.confirm)act('cancel')}})}
async function init(){try{if(!token){const r=await request('participants',{});token=r.token;uni.setStorageSync('pilot-token',token)}await refresh();if(!hasLocalDraft && state.value.ticket?.profile)Object.assign(form,pickPreferences(state.value.ticket.profile))}catch(e){error.value=e.message}clearInterval(timer);timer=setInterval(async()=>{clock.value=Date.now();if(!busy.value&&++tick%4===0){await refresh();if(tab.value==='招募大厅')await loadCandidates()}},1000)}

onShow(init);onHide(()=>clearInterval(timer));onUnload(()=>clearInterval(timer))
</script>
